  "claim": {
    "component_id": "C015.component",
    "value": "Reducing concurrency tests whether contention contributes to export delays, without assuming that contention does contribute.",
    "scope": "Rationale for the direction of the proposed perturbation.",
    "provenance": {
      "refs": [
